insert into categories (position, name) values
  (1, 'Pricing'),
  (2, 'Choice'),
  (3, 'Risk'),
  (4, 'Social'),
  (5, 'Scarcity'),
  (6, 'Motivation'),
  (7, 'Perception'),
  (8, 'Trust');
insert into principles (id, category, name, aka, description, dark_pattern_example, dark_pattern_rating, dark_pattern_reason, healthy_example) values
  (1, 'Pricing', 'Anchoring', array['Anchoring Bias','Anchoring Effect']::text[], 'The first number or option people see becomes a reference point that skews how they judge everything after it.', 'The store shows a serum at $49 next to a crossed-out $85 it was never sold for.', 4, 'A fake price is misleading, and degrades trust.', 'The store only shows a crossed-out $85 if the serum was really sold at that price recently.'),
  (2, 'Pricing', 'Decoy Effect', array['Asymmetric Dominance']::text[], 'Adding a clearly inferior option makes a nearby target option look better by comparison.', 'The store adds a $32 medium moisturizer that only exists to make the $34 large look like a steal.', 3, 'A fake option steers shoppers, and feels sneaky once noticed.', 'The store offers small, medium and large sizes that each suit a real need.'),
  (3, 'Pricing', 'Charm Pricing', array['Left-Digit Effect','Price Ending']::text[], 'Prices ending in .99 or .95 are perceived as noticeably lower because people anchor on the left-most digit.', 'The store prices a lipstick at $19.99 so it feels closer to $19 than $20.', 2, 'It''s a mild trick that most shoppers accept.', 'The store uses $19.99 pricing but shows the full total clearly at checkout.'),
  (4, 'Pricing', 'Price Relativity', '{}', 'People judge value relative to what''s around it, not in absolute terms.', 'The store places a $45 foundation next to a $120 one so the $45 feels cheap.', 2, 'It nudges spending, but nothing is hidden.', 'The store compares foundations side by side by size and ingredients, not just price.'),
  (5, 'Pricing', 'Mental Accounting', '{}', 'People put money into separate mental ''pots'' (gifts, treats, essentials) and spend differently from each.', 'The store labels a $30 face mask a ''self-care treat'' to make it feel guilt-free.', 2, 'It softens spending, which can lead to buyer''s regret.', 'The store offers an ''Under $15'' section to help shoppers stick to a budget.'),
  (6, 'Pricing', 'Pain of Paying', array['Payment Decoupling']::text[], 'Paying feels like a loss; the more visible and immediate the payment, the more it hurts.', 'The store pushes ''Pay in 4'' on every product page so a $90 bundle feels cheap.', 3, 'Hiding the real cost encourages debt, and causes regret later.', 'The store shows the full $90 total and payment schedule before shoppers choose ''Pay in 4''.'),
  (7, 'Pricing', 'Zero-Price Effect', array['Free Effect']::text[], '''Free'' has a disproportionate pull, far stronger than a small price reduction.', 'The store offers free shipping over $35, so a shopper adds a $6 lip balm they don''t need.', 2, 'It nudges a bigger basket, but the deal is clear.', 'The store suggests refills of products the shopper already uses to reach free shipping.'),
  (8, 'Pricing', 'Partitioned Pricing', '{}', 'Splitting a price into parts (or revealing fees late) makes the total feel lower. Often seen as a dark pattern.', 'The store adds a $4.50 delivery fee and a $1 packaging fee on the last checkout step.', 5, 'Hidden fees deceive shoppers, and destroy trust.', 'The store shows the full price, including delivery, on the product page.'),
  (9, 'Choice', 'Choice Overload', array['Paradox of Choice','Hick''s Law']::text[], 'Too many options increase decision time and can lead to no decision at all.', 'The store shows all 140 foundation shades on one huge page.', 2, 'Too many options overwhelm shoppers, so they leave without buying.', 'The store offers a 3-question quiz that narrows the shades down to 4 matches.'),
  (10, 'Choice', 'Default Effect', array['Default Bias','Status Quo Bias']::text[], 'People tend to stick with whatever option is pre-selected.', 'The store pre-selects a $25 monthly subscription at checkout.', 4, 'Shoppers get charged without meaning to, and feel tricked.', 'The store defaults to a one-off purchase and offers the subscription as a clear opt-in.'),
  (11, 'Choice', 'Framing Effect', '{}', 'The same information leads to different decisions depending on how it''s presented.', 'The store says ''97% saw fewer breakouts'' but hides that only 30 people were tested.', 3, 'Selective facts mislead shoppers, and erode trust when found out.', 'The store says ''97% saw fewer breakouts'' and links to the full study.'),
  (12, 'Choice', 'Compromise Effect', array['Extremeness Aversion']::text[], 'When given three options, people tend to choose the middle one to avoid extremes.', 'The store makes the $35 gift set the obvious pick, even though the $15 set suits most shoppers.', 3, 'Steering people away from what suits them erodes trust.', 'The store explains who each gift set is for, so shoppers pick the right one.'),
  (13, 'Choice', 'Choice Architecture', array['Nudge']::text[], 'The way choices are laid out shapes which one people pick, without removing any options.', 'The store hides the cheapest shipping option below the fold at checkout.', 3, 'Burying options costs shoppers money, and feels unfair.', 'The store lists every shipping option clearly, with the eco option highlighted.'),
  (14, 'Choice', 'Cognitive Load', array['Cognitive Overload']::text[], 'People have limited mental capacity; extra effort or information reduces completion and good decisions.', 'The store makes canceling a subscription a confusing 6-step process.', 4, 'Deliberate friction traps shoppers, and breeds resentment.', 'The store lets shoppers cancel a subscription in one click.'),
  (15, 'Choice', 'Satisficing', '{}', 'Most people pick the first option that''s ''good enough'' rather than searching for the best.', 'The store puts a ''Best for dry skin'' badge on its highest-profit moisturizer.', 3, 'A biased badge misleads shoppers, and damages credibility.', 'The store awards ''Best for dry skin'' badges based on reviews and ingredients.'),
  (16, 'Risk', 'Loss Aversion', '{}', 'Losses feel roughly twice as painful as equivalent gains feel good.', 'The store emails ''Don''t lose your $5 credit!'' two days before it expires.', 3, 'Fear of loss rushes shoppers, and can feel pushy.', 'The store reminds shoppers about their $5 credit a week before it expires.'),
  (17, 'Risk', 'Endowment Effect', '{}', 'People value things more once they feel they own them.', 'The store sends a free trial serum, then charges $60 if it isn''t returned within 7 days.', 4, 'Surprise charges make shoppers feel tricked.', 'The store sends a free sample with no strings attached.'),
  (18, 'Risk', 'Sunk Cost Fallacy', '{}', 'People continue investing in something because of what they''ve already put in.', 'The store tells shoppers they''re 80 points from a reward, then raises the target.', 4, 'Moving the goalposts exploits effort already spent, and breaks trust.', 'The store keeps reward targets fixed, and points never expire.'),
  (19, 'Risk', 'Risk Aversion', '{}', 'People avoid choices with unclear outcomes; reducing uncertainty increases action.', 'The store advertises free returns but charges a $7 restocking fee on opened items.', 4, 'Hidden conditions mislead shoppers, and damage trust.', 'The store offers free returns, even on opened products.'),
  (20, 'Risk', 'Zero-Risk Bias', '{}', 'People prefer eliminating a small risk completely over reducing a larger risk partially.', 'The store sells $8 ''breakage protection'' that the courier already covers for free.', 4, 'Selling fake peace of mind wastes money, and erodes trust.', 'The store offers a simple money-back guarantee with no conditions.'),
  (21, 'Social', 'Social Proof', array['Bandwagon Effect','Herd Behavior']::text[], 'People copy what others are doing, especially under uncertainty.', 'The store shows ''2,341 bought this week'' when the number is made up.', 5, 'Fake numbers deceive shoppers, and destroy credibility.', 'The store only shows real purchase numbers from the last 7 days.'),
  (22, 'Social', 'Authority Bias', '{}', 'People trust and follow perceived experts or credible institutions.', 'The store adds a ''Dermatologist recommended'' badge with no named expert behind it.', 4, 'An unbacked claim misleads shoppers, and damages credibility.', 'The store names the dermatologist behind the ''recommended'' badge.'),
  (23, 'Social', 'Liking / Similarity', '{}', 'People are more persuaded by those they like or who seem similar to them.', 'The store shows paid influencer reviews styled to look like regular customers.', 5, 'Disguised ads deceive shoppers, and destroy trust.', 'The store lets shoppers filter reviews by ''skin like mine'' and labels paid reviews.'),
  (24, 'Social', 'Reciprocity', '{}', 'When given something, people feel obliged to give something back.', 'The store adds a free mini lip oil, then sends daily emails pushing the $28 full size.', 3, 'Turning a gift into pressure feels pushy, and annoys shoppers.', 'The store adds a free mini lip oil as a thank-you, with no sales follow-up.'),
  (25, 'Social', 'Commitment', array['Foot-in-the-door']::text[], 'Once people make a small commitment, they''re more likely to follow through with bigger, consistent actions.', 'The store makes shoppers enter their email to see their skin quiz results.', 3, 'Gating results feels like a bait and switch.', 'The store shows skin quiz results right away, with no sign-up needed.'),
  (26, 'Scarcity', 'Scarcity Effect', '{}', 'Things seem more valuable when they appear limited.', 'The store shows ''Only 3 left!'' on every product, all the time.', 5, 'Fake scarcity deceives shoppers, and destroys trust.', 'The store only shows stock levels when they''re real.'),
  (27, 'Scarcity', 'Urgency', array['Deadline Effect','FOMO']::text[], 'Time limits push people to act sooner rather than defer.', 'The store shows a sale countdown that resets every time the page reloads.', 5, 'A fake deadline deceives shoppers, and breaks trust.', 'The store only uses countdowns for real sales that end when stated.'),
  (28, 'Scarcity', 'Exclusivity', '{}', 'Access that feels restricted to a select group increases desire.', 'The store hides its best prices behind a $9.99 monthly membership.', 3, 'Locking deals behind a fee feels exclusionary, and pushes spending.', 'The store gives members early access to new launches, with the same prices for everyone.'),
  (29, 'Motivation', 'Goal-Gradient Effect', '{}', 'People speed up as they get closer to a goal.', 'The store''s free shipping bar says ''$4 to go'' but only suggests $20 products.', 3, 'It pushes shoppers to overspend, and feels manipulative.', 'The store''s free shipping bar suggests small, useful items like refills.'),
  (30, 'Motivation', 'Endowed Progress Effect', '{}', 'Giving people artificial head-start progress makes them more likely to complete a goal.', 'The store gives 2 free loyalty stamps, then quietly makes stamps expire after 30 days.', 3, 'Hidden expiry rules frustrate shoppers, and erode loyalty.', 'The store gives 2 free loyalty stamps that never expire.'),
  (31, 'Motivation', 'Variable Rewards', array['Intermittent Reinforcement']::text[], 'Unpredictable rewards are more motivating and habit-forming than predictable ones.', 'The store shows a ''spin to win'' wheel after every purchase.', 3, 'Gambling-style rewards build compulsive habits.', 'The store gives a free sample of the shopper''s choice with every 5th order.'),
  (32, 'Motivation', 'Hyperbolic Discounting', array['Present Bias']::text[], 'People prefer smaller rewards now over bigger rewards later.', 'The store offers 15% off today only if shoppers open a store credit card.', 4, 'A quick reward hides a long-term cost, and can lead to debt.', 'The store offers 15% off a first order with no strings attached.'),
  (33, 'Motivation', 'Zeigarnik Effect', '{}', 'People remember and feel pulled to finish incomplete tasks.', 'The store nags ''Your profile is 60% complete'' until shoppers share their phone number.', 3, 'Pressuring for personal data feels intrusive, and erodes trust.', 'The store explains why each profile detail helps, and makes every field optional.'),
  (34, 'Motivation', 'IKEA Effect', array['Effort Justification']::text[], 'People value things more when they''ve helped create them.', 'The store lets shoppers build a custom gift box, then adds a $5 ''assembly fee'' at checkout.', 4, 'A surprise fee exploits the effort shoppers put in, and feels unfair.', 'The store lets shoppers build a custom gift box with a running total on screen.'),
  (35, 'Perception', 'Peak-End Rule', '{}', 'People judge an experience mostly by its most intense moment and how it ended.', 'The store ends every order with a delightful animation, but makes returns a hassle.', 2, 'A nice ending masks a poor experience that shoppers remember later.', 'The store ends each order with a friendly thank-you and clear tracking info.'),
  (36, 'Perception', 'Serial Position Effect', array['Primacy & Recency']::text[], 'People remember the first and last items in a list best.', 'The store always puts its highest-profit products first and last in search results.', 2, 'It quietly steers shoppers, and can hide better options.', 'The store orders search results by relevance and labels sponsored items.'),
  (37, 'Perception', 'Von Restorff Effect', array['Isolation Effect']::text[], 'The item that stands out visually is the one most likely to be noticed and remembered.', 'The store labels its $40 premium plan ''Most popular'' when it isn''t.', 4, 'A false label misleads shoppers, and damages trust.', 'The store highlights the plan that''s genuinely best for most shoppers.'),
  (38, 'Perception', 'Aesthetic-Usability Effect', array['Halo Effect']::text[], 'People assume attractive designs work better and attribute positive traits based on one good impression.', 'The store uses heavily retouched before-and-after photos for a wrinkle cream.', 4, 'Fake results mislead shoppers, and lead to disappointment.', 'The store shows unretouched photos from real customers.'),
  (39, 'Perception', 'Mere Exposure Effect', array['Familiarity Principle']::text[], 'The more people see something, the more they tend to like it.', 'The store follows shoppers around the web with ads for a product they viewed once.', 3, 'Constant tracking feels creepy, and erodes trust.', 'The store shows recently viewed items only on its own site.'),
  (40, 'Perception', 'Priming', '{}', 'Exposure to one stimulus unconsciously influences response to the next.', 'The store shows spa-style images and ''You deserve this'' copy before $120 night creams.', 2, 'It sets a spending mood, but nothing is hidden.', 'The store pairs calming images with clear prices and ingredients.'),
  (41, 'Trust', 'Confirmation Bias', '{}', 'People seek and favor information that supports what they already believe.', 'The store labels products ''toxin-free'' to match what clean beauty shoppers already believe.', 3, 'Vague claims exploit beliefs, and spread misinformation.', 'The store explains what its ''clean'' label actually means.'),
  (42, 'Trust', 'Ambiguity Effect', '{}', 'People avoid options where key information is missing.', 'The store leaves the ingredient list off its bestselling serum.', 3, 'Missing info stops informed choices, and erodes trust.', 'The store shows the full ingredient list on every product.'),
  (43, 'Trust', 'Labor Illusion', array['Operational Transparency']::text[], 'People value results more when they can see the effort behind them.', 'The store adds a fake 5-second ''Analyzing your skin...'' delay before quiz results.', 3, 'Faking effort is misleading, and feels cheap when noticed.', 'The store only shows progress messages while the tool is actually working.');
insert into meta (key, value) values
  ('title', '"Behavioral economics & consumer psychology principles for UX/Product"'::jsonb),
  ('exampleStore', '"A fictional online beauty store"'::jsonb),
  ('darkPatternScale', '{"1": "Helpful - in the user''s interest", "2": "Mild nudge - transparent persuasion", "3": "Pressure - pushes quick or bigger decisions", "4": "Manipulative - works against the user''s interest", "5": "Deceptive - actively misleads the user"}'::jsonb),
  ('darkPatternNote', '"Ratings judge the dark pattern example, not the principle itself."'::jsonb);
