-- Good Nudge content. Paste this whole file into Supabase > SQL Editor and press Run.
-- Safe to run again: it rebuilds the three tables from scratch.

drop table if exists principles; drop table if exists categories; drop table if exists meta;

create table categories (position int primary key, name text not null unique);
create table principles (id int primary key, category text not null references categories(name), name text not null, aka text[] not null default '{}', description text not null, dark_pattern_example text not null, dark_pattern_rating int not null check (dark_pattern_rating between 1 and 5), dark_pattern_reason text not null, healthy_example text not null);
create table meta (key text primary key, value jsonb not null);

-- Anyone can read (the site and Claude only read). Nobody can write without the Supabase dashboard or a secret key.

